// A: Numero massimo di buchi
float numHoles = max(floor(A), 1.0); 

// Offset per mantenere la scultura perfettamente centrata
float offset_u = (numHoles - 1.0) / 2.0;

// Inizializzazioni
float d_final = 10000.0; 

// --- DEFORMAZIONE TOPOLOGICA CONTINUA ---
float anim_scale = 0.5 + 0.5 * cos(F * ubuf.u_time);

float max_L = offset_u * max(D, 0.1);
float current_L = max_L * anim_scale;

// IL TRUCCO ANTISALTO: Scaliamo la morbidezza (E) insieme alla distanza. 
// Quando i tori si sovrappongono (anim_scale = 0), E diventa minuscolo (0.005).
// Questo evita l'effetto "palloncino" e rimuove la necessità di usare 'if' che causano scatti.
float current_E = max(E * anim_scale, 0.005); 

for(int k = int(0.0); k < int(20.0); k++) {
    float fk = float(k);

    if(fk < numHoles) { 
        // Posizione target teorica
        float target_cx = (fk - offset_u) * max(D, 0.1);

        // Lo scivolamento fisico, ora fluido al 100%
        float cx = clamp(target_cx, -current_L, current_L);

        vec3 p_ring = vec3(p.x - cx, p.y, p.z);

        // Geometria costante, nessuna variazione
        float d_ring = length(vec2(length(p_ring.xy) - B, p_ring.z)) - C;

        if(k == int(0.0)) {
            d_final = d_ring; // Base della scultura
        } else {
            // Fusione sempre attiva, ma proporzionale all'apertura!
            d_final = -smax(-d_final, -d_ring, current_E);
        }
    }
}

return d_final;
